using Sistema3S.Tests.Fixtures;
using Sistema3S.Web.Services.Bi;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Validation;
namespace Sistema3S.Tests.Integration;
public sealed class BiMejoraTests
{
    [Fact(DisplayName="PI-BIM-001 | Comparación realmente apagada, automática y doce días aceptados")]
    public async Task Comparacion(){await using var db=await QaDatabase.CreateAsync();await BiTests.Migrar(db);await BiReferencia.PrepararAsync(db);var f=BiTests.Filtro("referencia");f.Desde=new(2026,10,1);f.Hasta=new(2026,10,12);f.ModoComparacion="ninguna";f.CompararDesde=new(2026,9,1);f.CompararHasta=new(2026,9,30);var service=BiTests.Servicio(db);var off=await service.ConsultarAsync("ventas",f,default);Assert.Null(off.CompararDesde);Assert.Empty(off.Datos["evolucionComparacion"]);Assert.All(off.Datos["kpis"],k=>{Assert.Null(k["Anterior"]);Assert.Null(k["VariacionAbsoluta"]);});f.ModoComparacion="anterior";var auto=await service.ConsultarAsync("ventas",f,default);Assert.Equal(new DateOnly(2026,9,19),auto.CompararDesde);Assert.Equal(new DateOnly(2026,9,30),auto.CompararHasta);f.ModoComparacion="personalizado";f.CompararDesde=new(2026,9,19);f.CompararHasta=new(2026,9,30);var custom=await service.ConsultarAsync("ventas",f,default);Assert.Equal(auto.Datos["kpis"].Single(k=>Equals(k["Tipo"],"venta"))["Anterior"],custom.Datos["kpis"].Single(k=>Equals(k["Tipo"],"venta"))["Anterior"]);}
    [Fact(DisplayName="PI-BIM-002 | Indicadores especializados, recurrencia y hallazgos sustentados")]
    public async Task Lectura(){await using var db=await QaDatabase.CreateAsync();await BiTests.Migrar(db);await BiReferencia.PrepararAsync(db);var service=BiTests.Servicio(db);foreach(var vista in new[]{"ventas","productos","clientes","compras","inventario"}){var r=await service.ConsultarAsync(vista,BiTests.Filtro("referencia"),default);Assert.InRange(r.Indicadores.Count,4,6);if(vista=="ventas")Assert.DoesNotContain(r.Indicadores,k=>k.Etiqueta.Contains("Compra")||k.Etiqueta.Contains("Cotiza"));if(vista=="compras")Assert.DoesNotContain(r.Indicadores,k=>k.Etiqueta.Contains("venta",StringComparison.OrdinalIgnoreCase));if(vista!="inventario")Assert.All(r.Datos["operaciones"],x=>Assert.Equal(vista=="compras"?"compra":vista=="clientes"?"cotizacion":"venta",x["Tipo"]));}var resumen=await service.ConsultarAsync("resumen",BiTests.Filtro("referencia"),default);Assert.InRange(resumen.Hallazgos.Count,1,6);Assert.Contains(resumen.Hallazgos,h=>h.Titulo=="Seguimiento de cotizaciones");Assert.All(resumen.Hallazgos,h=>{Assert.NotEmpty(h.Evidencia);Assert.NotEmpty(h.AccionSugerida);Assert.DoesNotContain("garantizado",h.ImpactoEsperado);});}
    [Fact(DisplayName="PI-BIM-003 | Todos los XLSX validan el paquete completo y no ejecutan textos como fórmulas")]
    public async Task Excel(){await using var db=await QaDatabase.CreateAsync();await BiTests.Migrar(db);await BiReferencia.PrepararAsync(db);await using var api=await ApiHost.Start(db);await ApiTests.Login(api);await db.Exec("UPDATE ElementoCatalogo SET Nombre=N'=HYPERLINK(\"https://example.test\",\"x\")' WHERE IdElementoCatalogo=5");foreach(var vista in new[]{"resumen","ventas","productos","clientes","compras","inventario"}){var response=await api.Http.GetAsync($"/api/bi/{vista}/excel?desde=2026-04-01&hasta=2026-10-12&procedencia=referencia&elemento=5");response.EnsureSuccessStatusCode();var bytes=await response.Content.ReadAsByteArrayAsync();using var doc=SpreadsheetDocument.Open(new MemoryStream(bytes),false);Assert.Empty(new OpenXmlValidator().Validate(doc));using var libro=new ClosedXML.Excel.XLWorkbook(new MemoryStream(bytes));Assert.All(libro.Worksheets.SelectMany(s=>s.CellsUsed()),cell=>Assert.False(cell.HasFormula));Assert.Contains(libro.Worksheets.SelectMany(s=>s.CellsUsed()),cell=>cell.GetString().StartsWith("=HYPERLINK"));Assert.IsType<DateTime>(libro.Worksheet("Gráfico").Cell(20,1).GetValue<DateTime>());}}
}
